UIProjectileImage=function(game,gameController){Phaser.Image.call(this,game,0,0,'game','');this.gameController=gameController;this.anchor.setTo(0.5,0.5);this.scale.setTo(UIConstants.GAME_ASSET_SCALE,UIConstants.GAME_ASSET_SCALE);this.kill();};UIProjectileImage.prototype=Object.create(Phaser.Image.prototype);UIProjectileImage.prototype.constructor=UIProjectileImage;UIProjectileImage.prototype.update=function(){if(!this.exists){return;}var projectile=this.gameController.getProjectile(this.projectileId);if(projectile){this.x=UIUtils.mpx(projectile.getX());this.y=UIUtils.mpx(projectile.getY());}};UIProjectileImage.prototype.spawn=function(x,y,projectileId,frameName){this.frameName=frameName;this.reset(x,y);this.projectileId=projectileId;};UIProjectileImage.prototype.remove=function(){this.kill();};UIProjectileImage.prototype.retire=function(){this.kill();};